package dev.veltraph.client.navigation;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
/** Pure identity conformance only; no native receipt, cause, Root or publication can be manufactured here. */
class LegacyGuiCleanupConsumptionTest {
 final Object root=new Object(),parent=new Object(),player=new Object(),world=new Object(),connection=new Object(),config=new Object(),service=new Object(),leg=new Object();
 LegacyTravelPublicationIdentity.State state(long g,long e,long s,Object camera,long revision){return new LegacyTravelPublicationIdentity.State(root,parent,parent,camera,player,world,connection,config,revision,7,service,g,e,s,leg,true,true,camera!=null);}
 LegacyTravelPublicationIdentity.Lease queued(boolean adopted){var initial=state(4,9,20,parent,3);var next=LegacyTravelPublicationIdentity.Lease.capture(initial);assertNotNull(next);assertTrue(next.inputPublished(initial,initial));assertTrue(next.queued(initial,state(5,9,20,parent,3)));if(adopted)assertTrue(next.refreshedSource(state(5,9,20,parent,3),state(5,9,21,parent,3),5,9,21));return next;}
 LegacyTravelPublicationIdentity.State gui(long e){return state(6,e,21,null,5);}
 @Test void actualQualifiedGuiRetirementKeepsKeysButNeverCameraOrGameplay(){var l=queued(true);assertTrue(l.retiredGuiCleanup(gui(10),9,10,21));assertTrue(l.cleanupCurrent(gui(10)));assertTrue(l.mayReleaseKeys(gui(10)));assertFalse(l.current(gui(10)));assertFalse(l.mayCancelCamera(gui(10)));assertFalse(l.cameraPublishedOrQueued());assertTrue(l.guiCleanupOnly());}
 @Test void qualifiedOwnPublicationCanBeConsumedAtomicallyWithoutLateForeignTicketAdoption(){var l=queued(false);assertTrue(l.retiredGuiCleanup(gui(10),9,10,21));assertEquals(21,l.serial());assertEquals(0,l.ticket());assertFalse(l.current(state(6,10,21,parent,3)));}
 @Test void certificateDescendantUpdatesCleanupOnlyWithoutAnotherRequestOrCameraCancellation(){var l=queued(true);assertTrue(l.retiredGuiCleanup(gui(10),9,10,21));assertTrue(l.advancedGuiCleanup(gui(12),10,12));assertEquals(6,l.generation());assertEquals(12,l.epoch());assertTrue(l.mayReleaseKeys(gui(12)));assertFalse(l.mayCancelCamera(gui(12)));assertFalse(l.current(state(6,12,21,parent,3)));}
 @Test void ordinaryNumericEpochJumpStillCannotAdvanceGuiCleanup(){var l=queued(true);assertFalse(l.cleanupCurrent(gui(10)));assertFalse(l.advancedGuiCleanup(gui(10),9,10));assertEquals(9,l.epoch());assertTrue(l.cameraPublishedOrQueued());}
 @Test void wrongOriginalGuiEpochOrSourceTicketDoesNotSpendQueue(){for(long[] bad:new long[][]{{8,10,21},{11,12,21},{9,10,20},{9,10,22},{9,9,21}}){var l=queued(true);assertFalse(l.retiredGuiCleanup(gui(bad[1]),bad[0],bad[1],bad[2]));assertEquals(5,l.generation());assertEquals(9,l.epoch());assertTrue(l.cameraPublishedOrQueued());}}
 @Test void duplicateRequestRetirementDoesNotAdvanceGeneration(){var l=queued(true);assertTrue(l.retiredGuiCleanup(gui(10),9,10,21));assertFalse(l.retiredGuiCleanup(gui(11),10,11,21));assertEquals(6,l.generation());assertEquals(10,l.epoch());}
 @Test void foreignRootPwcStoreServiceParentOrActiveLegCannotBorrowGuiCleanup(){for(String field:new String[]{"root","parent","input","player","world","connection","config","service","leg"}){var l=queued(true);assertFalse(l.retiredGuiCleanup(foreign(gui(10),field),9,10,21),field);assertEquals(5,l.generation());}}
 @Test void callbackNewRequestOrPublicationRejectsDescendantAndRetainsOldCleanupEndpoint(){var l=queued(true);assertTrue(l.retiredGuiCleanup(gui(10),9,10,21));assertFalse(l.advancedGuiCleanup(state(7,11,21,null,5),10,11));assertFalse(l.advancedGuiCleanup(state(6,11,22,null,5),10,11));assertEquals(10,l.epoch());}
 @Test void sameStorePolicyLossOnlyKeepsCleanupNotOriginalGameScene(){var l=queued(true);assertTrue(l.retiredGuiCleanup(gui(10),9,10,21));assertTrue(l.cleanupCurrent(state(6,10,21,null,999)));assertFalse(l.current(state(6,10,21,parent,3)));assertFalse(l.current(state(6,10,21,parent,999)));}
 @Test void closingGuiAndRestoringUsabilityCannotRenewClosedGameplayGearOrInteraction(){var l=queued(true);assertTrue(l.retiredGuiCleanup(gui(10),9,10,21));l.closed();var live=new LegacyTravelPublicationIdentity.State(root,parent,parent,parent,player,world,connection,config,3,7,service,6,10,21,null,true,true,true);assertFalse(l.ownsRetiredParent(live,true,8,8));assertFalse(l.ownsRetiredCleanupParent(live,true,8,8));assertFalse(l.ownsRetiredContinuation(live,true,8,8));assertFalse(l.consumeRetiredInteraction(live,true,8,8));}
 @Test void closeRevokesGuiKeyPermissionAndNeverMakesContinuation(){var l=queued(true);assertTrue(l.retiredGuiCleanup(gui(10),9,10,21));l.closed();assertFalse(l.cleanupCurrent(gui(10)));assertFalse(l.mayReleaseKeys(gui(10)));assertFalse(l.advancedGuiCleanup(gui(11),10,11));}
 private LegacyTravelPublicationIdentity.State foreign(LegacyTravelPublicationIdentity.State s,String field){return new LegacyTravelPublicationIdentity.State(field.equals("root")?new Object():s.root(),field.equals("parent")?new Object():s.parent(),field.equals("input")?new Object():s.inputOwner(),s.cameraAuthority(),field.equals("player")?new Object():s.player(),field.equals("world")?new Object():s.world(),field.equals("connection")?new Object():s.connection(),field.equals("config")?new Object():s.config(),s.revision(),s.journey(),field.equals("service")?new Object():s.service(),s.requestGeneration(),s.epoch(),s.publicationSerial(),field.equals("leg")?new Object():s.activeLeg(),s.registered(),s.enabled(),s.usable());}
}
